class MaxFlowSolver:
    def __init__(self, n: int):
        self.n = n
        self.capacity = [[0] * (n + 2) for _ in range(n + 2)]
        self.graph = [[] for _ in range(n + 2)]
        self.node_index = {i: i for i in range(n + 1)}
        self.node_index[n] = n + 1  # Sink
        self.flow_matrix = [[0] * 105 for _ in range(105)]

    def add_edge(self, u: int, v: int, cap: int, is_flow_cap: bool = False):
        self.graph[u].append((v, len(self.graph[v]), cap, is_flow_cap))
        self.graph[v].append((u, len(self.graph[u]) - 1, 0, is_flow_cap))

    def bfs(self, s: int, t: int, parent: List[int]) -> bool:
        visited = [False] * self.n
        for i in range(self.n + 2):
            self.visited = [False] * self.n
        queue = deque([(s, float('inf'))])
        self.visited[s] = True

        while queue:
            u, f = queue.popleft()
            if f == 0:
                continue
            for v, rev_idx, cap, is_flow_cap in self.graph[u]:
                if self.visited[v]:
                    continue
                rev_f = self.flow_matrix[u][v]
                if f > 0:
                    if cap == 0:
                        rev_f = 0
                    else:
                        from_flow = rev_f
                        if from_flow > 0:
                            new_f = f - min(from_flow, cap)
                        else:
                            new_f = f
                    if self.graph[u][0][2] != 0: # special check for max flow
                        new_f = 0

                    if self.visited[v]:
                        continue
                    if cap - new_f == 0 and new_f < f:
                        continue

                    self.visited[v] = True
                    parent[v] = u
                    queue.append((v, new_f))        
                    if v == t:
                        self.residual_cap = new_f
                        return True

        return False

    def max_flow(self, path: List[int]) -> Tuple[int, bool]:
        for u in reversed(path):
            v = u + 1
            old_cap = 0
            if self.capacity[u][v] > 0:
                old_cap = self.capacity[u][v]
            new_cap = self.capacity[u][v] - 1
            self.graph[u].append((v, len(self.graph[v]), new_cap, False))
            self.graph[v].append((u, len(self.graph[u]) - 1, 0, False))
        return old_cap, new_cap

    def solve_ns(self, a: List[int], b: List[int]) -> Tuple[bool, List[List[int]]]:
        self.total_s = sum(a)
        if self.total_s > 0:
            max_flow = sum(a)
            for i in range(self.n):
                for j in range(self.n):
                    if i == j:
                        self.capacity[self.node_index[i]][self.node_index[j]] = a[i]
                    else:
                        self.capacity[self.node_index[i]][self.node_index[j]] = 10000
            total_b = sum(b)
            if total_b != self.total_s:
                return False, []
        return True, []

    def output_solution(self, result: List[List[int]]) -> str:
        if result:
            return '\n'.join([ ' '.join(map(str, row)) for row in result])
        return ""

def solution(input_str: str) -> str:
    try:
        lines = input_str.strip().split('\n')
        if not lines:
            return "NO\n"

        parts = lines[0].split()
        if len(parts) < 2:
            return "NO\n"

        n = int(parts[0])
        m = int(parts[1])

        a = []
        for i in range(1, n + 1):
            try:
                a.append(int(lines[i]))
            except:
                a.append(0)

        b = []
        for i in range(n + 1, n + 1 + n):
            try:
                b.append(int(lines[i]))
            except:
                b.append(0)

        roads = set()
        for i in range(n + 1 + n, len(lines)):
            try:
                parts = lines[i].split()
                if len(parts) >= 2:
                    u = int(parts[0])
                    v = int(parts[1])
                    roads.add((min(u, v), max(u, v)))
            except:
                pass

        solver = MaxFlowSolver(n)
        result, sol = solver.solve_ns(a, b)

        if result and sol:
            return "YES\n" + '\n'.join([ ' '.join(map(str, row[:n])) for row in sol[:n]]) + '\n'
        return "NO\n"
    except:
        return "NO\n"

