def solution(input_str):
    from collections import defaultdict
    from heapq import heappop, heappush

    lines = input_str.strip('\n').split('\n')
    n, m, k = map(int, lines[0].split())

    idx = 1
    roads = []
    for _ in range(m):
        u, v, x = map(int, lines[idx].split())
        roads.append((u, v, x))
        idx += 1

    trains = []
    for _ in range(k):
        s, y = map(int, lines[idx].split())
        trains.append((s, y))
        idx += 1

    adj = defaultdict(list)
    for u, v, x in roads:
        adj[u].append((v, x))
        adj[v].append((u, x))

    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[1] = 0
    pq = [(0, 1)]

    while pq:
        d, u = heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heappush(pq, (dist[v], v))

    redundant_trains = []
    for s, y in trains:
        if dist[s] <= y:
            redundant_trains.append((s, y))

    if len(redundant_trains) == 0:
        return str(k)

    cities_count = defaultdict(int)
    for s, y in redundant_trains:
        cities_count[s] += 1

    closed = 0
    for count in cities_count.values():
        closed += max(0, count - 1)

    return str(k - closed)

