    # x and a-x must be together if both exist in array
    # x and b-x must be together if both exist in array
    adj = [[] for _ in range(n)]
    for i in range(n):
        # Add edge for a-complement relationship
        target = a - p[i]
        if target in pos:
            adj[i].append(pos[target])
            adj[pos[target]].append(i)

        # Add edge for b-complement relationship
        target = b - p[i]
        if target in pos:
            adj[i].append(pos[target])
            adj[pos[target]].append(i)

    visited = [False] * n
    ans = [0] * n  # 0 for set A, 1 for set B
    possible = True

    for start in range(n):
        if visited[start]:
            continue

        # BFS to find connected component
        component = []
        q = [start]
        visited[start] = True

        while q:
            u = q.pop(0)
            component.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)

        # Check if this component can be placed in set A
        can_be_in_A = True
        for u in component:
            target = a - p[u]
            if target in pos:
                if pos[target] not in component:
                    can_be_in_A = False
                    break

        # Check if this component can be placed in set B
        can_be_in_B = True
        for u in component:
            target = b - p[u]
            if target in pos:
                if pos[target] not in component:
                    can_be_in_B = False
                    break

        # If neither placement is valid, impossible
        if not can_be_in_A and not can_be_in_B:
            possible = False
            break

        # Assign all nodes in component to the same set
        if can_be_in_A:
            for idx in component:
                ans[idx] = 0
        else:
            for idx in component:
                ans[idx] = 1

    if not possible:
        return "NO\n"

    return "YES\n" + ' '.join(map(str, ans)) + '\n'

