        if r <= max_val:
            group[r].append(i)
            available_revs.add(r)

    # Build prefix count arrays for each reverse value
    # pref_counts[r][k] = count of numbers in [1, k] with rev = r
    pref_counts = []
    for r in range(max_val + 1):
        idx = group[r]
        pref = [0] * (max_val + 1) if maxx >= max_val else [0] * (maxx + 1)
        j = 0
        for k in range(1, max_val + 1):
            if k <= maxx and j < len(idx) and idx[j] == k:
                j += 1
            pref[k] = min(j, len(idx))
        pref_counts.append(pref[:maxx + 1])

